DROP TABLE IF EXISTS customer_master;
CREATE TABLE customer_master (CUST_ID TEXT
CUST_AGE INTEGER
CUST_OCCUPATION TEXT
CUST_INCOME_LEVEL TEXT
CUST_REGION TEXT
CUST_PHONE TEXT
CUST_SEGMENT TEXT);

DROP TABLE IF EXISTS contract_snapshot;
CREATE TABLE contract_snapshot (CONTRACT_NO TEXT
CUST_ID TEXT
DPD_CURRENT INTEGER
PRNC_OTS DECIMAL
INTR_OTS DECIMAL
CYCLE_AKHIR TEXT
PRODUCT_TYPE TEXT);

DROP TABLE IF EXISTS payment_history;
CREATE TABLE payment_history (PAYMENT_ID TEXT
CONTRACT_NO TEXT
DUE_DATE TEXT
ACTUAL_PAY_DATE TEXT
PAYMENT_AMOUNT DECIMAL
PAY_STATUS TEXT
PAY_METHOD TEXT
DELAY_DAYS INTEGER);

DROP TABLE IF EXISTS lkp_interaction;
CREATE TABLE lkp_interaction (LKP_ID TEXT
CONTRACT_NO TEXT
ACTION_DATE TEXT
TREATMENT_TYPE TEXT
RESULT_CODE TEXT
PROMISE_DATE TEXT
COLLECTOR_ID TEXT
INTERACTION_SCORE INTEGER);

DROP TABLE IF EXISTS ai_intelligence;
CREATE TABLE ai_intelligence (CONTRACT_NO TEXT
RECOVERY_SCORE DECIMAL
RISK_SEGMENT TEXT
NBA_RECOMMENDATION TEXT
PRIORITY_LEVEL TEXT
CONFIDENCE_LEVEL DECIMAL);

